 var p=ensurePet(),logs=p.careLog.filter(function(x){return x.date===today();}),limit={feed:3,play:1,rest:1,clean:1}[action];if(!limit)return;
 if(logs.filter(function(x){return x.action===action;}).length>=limit)return toast('На сегодня этого достаточно. Завтра можно продолжить.','info');
