/* LIBRARY EXPLORERS — turn legacy placeholder screens into usable, searchable sections */
function lifeLibraryItems(source){
 return Array.isArray(source)?source:[];
}
function lifeLibraryText(item){
 return [item.title,item.name,item.cat,item.role,item.what,item.theory,item.desc,item.where,item.when].filter(Boolean).join(' ').toLowerCase();
}
function renderLifeLibrary(title,subtitle,items,opts){
 opts=opts||{};items=lifeLibraryItems(items);var progress=state.libraryProgress||{},done=items.filter(function(x){return progress[x.id];}).length;
 var categories=Array.from(new Set(items.map(function(x){return x.cat||x.role||'Общее';}))),html='<div class="page"><div class="title-xl">'+esc(title)+'</div><div class="subtitle">'+esc(subtitle)+'</div><div class="grid-2 mb-3"><div class="card"><div class="stat-value">'+items.length+'</div><div class="stat-label">Материалов</div></div><div class="card"><div class="stat-value">'+done+'</div><div class="stat-label">Изучено</div></div></div><div class="field"><input id="lifeLibrarySearch" placeholder="Поиск по названию и содержанию…" oninput="filterLifeLibrary(\''+opts.key+'\')"></div><div class="row wrap mb-3"><button class="btn btn-primary btn-xs" onclick="filterLifeLibraryCategory(\''+opts.key+'\',\'all\')">Все</button>'+categories.map(function(c){return '<button class="btn btn-ghost btn-xs" onclick="filterLifeLibraryCategory(\''+opts.key+'\',\''+esc(c).replace(/'/g,'&#39;')+'\')">'+esc(c)+'</button>';}).join('')+'</div><div id="lifeLibraryResults">'+renderLifeLibraryRows(items,opts.key)+'</div></div>';
 window.__lifeLibraryData=window.__lifeLibraryData||{};window.__lifeLibraryData[opts.key]=items;document.getElementById('app').innerHTML=html;
}
function renderLifeLibraryRows(items,key){
 if(!items.length)return '<div class="card empty">По запросу ничего не найдено.</div>';
 var p=state.libraryProgress||{};
 return items.map(function(x){var title=x.title||x.name||'Материал',cat=x.cat||x.role||'Общее';return '<button class="card mb-2" style="width:100%;text-align:left" onclick="openLifeLibraryItem(\''+key+'\',\''+String(x.id||'').replace(/'/g,'')+'\')"><div class="row-between"><b>'+esc((x.emoji||'📘')+' '+title)+'</b><span class="badge">'+(p[x.id]?'✓ Изучено':esc(cat))+'</span></div><div class="footnote mt-2">'+esc(String(x.desc||x.what||x.theory||x.role||'').replace(/[*#]/g,'').slice(0,180))+'</div></button>';}).join('');
}
window.filterLifeLibrary=function(key){var q=String((document.getElementById('lifeLibrarySearch')||{}).value||'').toLowerCase(),items=(window.__lifeLibraryData||{})[key]||[],cat=window.__lifeLibraryCategory||'all';var host=document.getElementById('lifeLibraryResults');if(host)host.innerHTML=renderLifeLibraryRows(items.filter(function(x){return (!q||lifeLibraryText(x).includes(q))&&(cat==='all'||(x.cat||x.role||'Общее')===cat);}),key);};
window.filterLifeLibraryCategory=function(key,cat){window.__lifeLibraryCategory=cat;window.filterLifeLibrary(key);};
window.openLifeLibraryItem=function(key,id){
 var x=((window.__lifeLibraryData||{})[key]||[]).find(function(v){return String(v.id)===String(id);});if(!x)return;
 var title=x.title||x.name||'Материал',body='<div class="footnote">'+esc(x.cat||x.role||'')+'</div>';
 [['Суть',x.theory||x.what||x.desc],['Роль',x.role],['Где работает',x.where],['Когда активен',x.when],['Практика',Array.isArray(x.practice)?x.practice.join('\n'):x.practice],['Что поддерживает',Array.isArray(x.up)?x.up.join(' · '):x.up],['Что может мешать',Array.isArray(x.down)?x.down.join(' · '):x.down],['Питание',x.food],['Сон',x.sleep],['Движение',x.sport],['Протокол',Array.isArray(x.protocol)?x.protocol.join('\n'):x.protocol],['Совет',x.tips]].forEach(function(pair){if(pair[1])body+='<div class="section-title mt-3">'+pair[0]+'</div><div class="body-text">'+esc(String(pair[1])).replace(/\n/g,'<br>')+'</div>';});
 if(x.science&&!/наука подтверждает|доказано|когнитивная наука подтверждает/i.test(x.science))body+='<div class="footnote mt-3">Источник/примечание: '+esc(x.science)+'</div>';
 body+='<div class="footnote mt-3">Справочный материал LIFEOS. Не используй его как диагноз или назначение лечения.</div><button class="btn btn-primary btn-block mt-3" onclick="markLifeLibraryDone(\''+key+'\',\''+String(id).replace(/'/g,'')+'\')">✓ Отметить изученным</button>';
 openSheet(title,body);
};
